def classify_status(code):
    if 100 <= code < 200:
        return "Informational"
    elif 200 <= code < 300:
        return "Success"
    elif 300 <= code < 400:
        return "Redirection"
    elif 400 <= code < 500:
        return "Client Error"
    elif 500 <= code < 600:
        return "Server Error"
    else:
        return "Unknown"

print(classify_status(403))

import requests

try:
    response = requests.get("http://httpbin.org/redirect/1", allow_redirects=False, timeout=5)
    print(f"Status: {response.status_code}")
    print(f"Location: {response.headers.get('Location')}")
except requests.exceptions.ConnectionError:
    # Fallback for offline: simulate
    class MockResponse:
        status_code = 302
        headers = {"Location": "https://new-url.com"}
    response = MockResponse()
    print(f"Status: {response.status_code}")
    print(f"Location: {response.headers.get('Location')}")

def check_auth_status(status_code):
    if status_code == 401:
        print("Please log in")
    elif status_code == 403:
        print("Access denied")
    else:
        print("Something else")

check_auth_status(401)
check_auth_status(403)
